using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static class RuinsAgingMaterialReview{
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Color32[] Shot(Camera c,string path){var rt=new RenderTexture(640,480,24);c.targetTexture=rt;for(int k=0;k<4;k++)c.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(640,480,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,640,480),0,0);t.Apply();if(path!=null)File.WriteAllBytes(path,t.EncodeToPNG());var data=t.GetPixels32();RenderTexture.active=prev;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(rt);return data;}
 static long Delta(Color32[] a,Color32[] b){long sum=0;for(int i=0;i<a.Length;i++)sum+=Math.Abs(a[i].r-b[i].r)+Math.Abs(a[i].g-b[i].g)+Math.Abs(a[i].b-b[i].b);return sum;}
 public static void Run(){const string ev="Evidence/Target46Material";Directory.CreateDirectory(ev);try{
  EditorSceneManager.OpenScene("Assets/RuinsTarget46Output/Room.unity");var root=GameObject.Find("ruins_1").transform.parent.gameObject;var camera=UnityEngine.Object.FindAnyObjectByType<Camera>();camera.orthographic=false;Vector3 lampPosition=new Vector3(-7,6,-5),lampTarget=new Vector3(-7,4,-7);camera.transform.position=new Vector3(-2,8,-2);camera.transform.LookAt(lampTarget);camera.backgroundColor=Color.black;
  var all=root.GetComponentsInChildren<MeshRenderer>().Where(r=>r.name!="TerrainCaps").ToArray();var materials=all.Select(r=>r.sharedMaterial).Distinct().ToArray();Check(all.Length==48&&materials.Length==3,"Sharing count");Check(all.Select(r=>r.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==36,"Mesh sharing");int triangleCount=all.Sum(r=>r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3);
  Check(materials.All(m=>m.shader.name=="MapRuins/AgedLimestone"&&!ShaderUtil.ShaderHasError(m.shader)),"Aged shader compilation");Check(materials.SelectMany(m=>new[]{m.GetTexture("_BaseMap"),m.GetTexture("_BumpMap"),m.GetTexture("_MetallicGlossMap")}).Distinct().Count()==3,"Textures shared");Check(materials.All(m=>m.IsKeywordEnabled("_RUINS_DETAIL_V3")),"V3 sampling keyword");var textures=materials.SelectMany(m=>new[]{m.GetTexture("_BaseMap"),m.GetTexture("_BumpMap"),m.GetTexture("_MetallicGlossMap")}).Distinct().ToArray();Check(textures.All(t=>t.width==512&&t.height==512),"Final texture dimensions");long textureBytes=textures.Sum(t=>UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(t));
  var args=Environment.GetCommandLineArgs();var exportDir=args[Array.IndexOf(args,"-ruinsExportDir")+1];
  var data=MapRuins.EditorTools.RuinsStructureImporter.Preflight(exportDir,new HashSet<string>{"separateAuthoringV1",MapRuins.EditorTools.RuinsStructureImporter.Feature});
  Check(data.items.Length==all.Length,"Export instance count");Check(triangleCount==data.items.Sum(i=>i.triangles.Length/3),"Export triangle count");
  foreach(var r in all){var a=r.GetComponent<MeshFilter>().sharedMesh;var item=data.items.Single(i=>i.id==r.name);
   Check(a.vertices.SelectMany(v=>new[]{v.x,v.y,v.z}).SequenceEqual(item.positions)&&a.normals.SelectMany(v=>new[]{v.x,v.y,v.z}).SequenceEqual(item.normals)&&a.uv.SelectMany(v=>new[]{v.x,v.y}).SequenceEqual(item.uv)&&a.triangles.SequenceEqual(item.triangles),"Formal mesh/normal/UV/topology mismatch "+r.name);
   Check(r.GetComponent<MeshCollider>().sharedMesh==a,"Collider mesh split");
  }

  var before=Shot(camera,null);UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget46Output/Structures/Ruins.prefab"));Check(Delta(before,Shot(camera,null))==0,"Prefab pixel persistence");
  const string scene="Assets/RuinsTarget46Output/MaterialPersistence.unity";EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),scene);EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);EditorSceneManager.OpenScene(scene);camera=UnityEngine.Object.FindAnyObjectByType<Camera>();Check(Delta(before,Shot(camera,null))==0,"Scene pixel persistence");
  var source=(UniversalRenderPipelineAsset)GraphicsSettings.defaultRenderPipeline;var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(l=>l.type==LightType.Directional);var rows=new List<string>();
  foreach(var mode in new[]{RenderingMode.Forward,RenderingMode.ForwardPlus}){
   var pipeline=UnityEngine.Object.Instantiate(source);var renderer=ScriptableObject.CreateInstance<UniversalRendererData>();renderer.renderingMode=mode;var so=new SerializedObject(pipeline);var list=so.FindProperty("m_RendererDataList");list.arraySize=1;list.GetArrayElementAtIndex(0).objectReferenceValue=renderer;so.FindProperty("m_AdditionalLightsRenderingMode").intValue=(int)LightRenderingMode.PerPixel;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;
   var lamp=new GameObject("Aging diagnostic lamp").AddComponent<Light>();lamp.type=LightType.Point;lamp.transform.position=lampPosition;lamp.range=9;lamp.intensity=7;lamp.shadows=LightShadows.Soft;
   Color32[] dark=null;foreach(var state in new[]{"off","main","SH","point","spot"}){sun.enabled=state=="main";lamp.enabled=state=="point"||state=="spot";lamp.type=state=="spot"?LightType.Spot:LightType.Point;lamp.spotAngle=60;lamp.transform.LookAt(lampTarget);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=state=="SH"?Color.gray*.35f:Color.black;var shot=Shot(camera,ev+"/"+mode+"-"+state+".png");if(state=="off")dark=shot;long difference=Delta(dark,shot);if(state!="off")Check(difference>1000,"Missing light "+mode+" "+state);rows.Add("{\"path\":\""+mode+"\",\"light\":\""+state+"\",\"rgbDeltaFromOff\":"+difference+"}");}
   UnityEngine.Object.DestroyImmediate(lamp.gameObject);GraphicsSettings.defaultRenderPipeline=source;QualitySettings.renderPipeline=source;UnityEngine.Object.DestroyImmediate(pipeline);UnityEngine.Object.DestroyImmediate(renderer);
  }
  Check(!ShaderUtil.ShaderHasError(Shader.Find("MapRuins/AgedLimestone")),"Shader variants failed");File.WriteAllText(ev+"/result.json","{\"pass\":true,\"geometryMatchesCurrentFormalExport\":true,\"triangles\":"+triangleCount+",\"renderers\":48,\"meshes\":36,\"materials\":3,\"textures\":3,\"textureSize\":512,\"runtimeTextureBytes\":"+textureBytes+",\"prefabPixelDelta\":0,\"scenePixelDelta\":0,\"lighting\":["+string.Join(",",rows)+"],\"gpuPerformanceMeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
